244 | 		Name:             opt.Name,
245 | 		Description:      opt.Description,
246 | 		IssueLabels:      opt.IssueLabels,
247 | 		Gitignores:       opt.Gitignores,
248 | 		License:          opt.License,
249 | 		Readme:           opt.Readme,
250 | 		IsPrivate:        opt.Private || setting.Repository.ForcePrivate,
251 | 		AutoInit:         opt.AutoInit,
252 | 		DefaultBranch:    opt.DefaultBranch,
253 | 		TrustModel:       repo_model.ToTrustModel(opt.TrustModel),
254 | 		IsTemplate:       opt.Template,
