263 | 			ctx.APIError(http.StatusUnprocessableEntity, err.Error())
264 | 		} else if errors.Is(err, util.ErrPermissionDenied) {
265 | 			ctx.APIError(http.StatusForbidden, err.Error())
266 | 		} else {
267 | 			ctx.APIErrorInternal(err)
268 | 		}
269 | 		return
270 | 	}
271 | 
272 | 	// reload repo from db to get a real state after creation
273 | 	repo, err = repo_model.GetRepositoryByID(ctx, repo.ID)
